# Generates assets/data/questions_ar.json (source of truth is this list; JSON is what the app reads)
import json
M = "mbti"; E = "enneagram"; A = "arfd"
qs = []
def add(system, dim, texts, topic="", reverse_ids=()):
    for t in texts:
        qs.append({"id": len(qs)+1, "system": system, "dimension": dim, "topic": topic, "reverse": (len(qs)+1) in reverse_ids, "text": t})
add(M,"E",["أشعر بالنشاط عندما أتفاعل مع مجموعة من الناس.","أحب التعبير عن أفكاري بصوت مسموع أثناء النقاش.","أستمتع بالتعرف على أشخاص جدد والمشاركة في الأنشطة الاجتماعية."])
